 1	package com.example.pahanaedubackend.util;
 2	
 3	import java.security.MessageDigest;
 4	import java.security.NoSuchAlgorithmException;
 5	
 6	public class PasswordUtil {
 7	 public static String hashPassword(String password) {
 8	 try {
 9	 MessageDigest md = MessageDigest.getInstance("SHA-256"); // Use SHA-256
 10	 byte[] hash = md.digest(password.getBytes());
 11	
 12	 // Convert byte array to hex string
 13	 StringBuilder hexString = new StringBuilder();
 14	 for (byte b : hash) {
 15	 String hex = Integer.toHexString(0xff & b);
 16	 if (hex.length() == 1)
 17	 hexString.append('0');
 18	 hexString.append(hex);
 19	 }
 20	
 21	 return hexString.toString();
 22	
 23	 } catch (NoSuchAlgorithmException e) {
 24	 throw new RuntimeException("Error hashing password", e);
 25	 }
 26	 }
 27	
 28	 public static boolean checkPassword(String plainPassword, String storedHash) {
 29	 return hashPassword(plainPassword).equals(storedHash);
 30	 }
 31	}
