 36	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 37	
 38	 stmt.setString(1, accountNumber);
 39	 ResultSet rs = stmt.executeQuery();
 40	
 41	 if (rs.next()) {
 42	 Customer customer = new Customer();
 43	 customer.setAccountNumber(rs.getString("account_number"));
 44	 customer.setFullName(rs.getString("full_name"));
 45	 customer.setAddress(rs.getString("address"));
 46	 customer.setTelephone(rs.getString("telephone"));// hashed password
 47	 return customer;
 48	 }
 49	
 50	 } catch (SQLException e) {
 51	 e.printStackTrace();
 52	 }
 53	 return null;
 54	 }
