 1	package com.example.pahanaedubackend.dao;
 2	
 3	import com.example.pahanaedubackend.model.User;
 4	import com.example.pahanaedubackend.util.DBUtil;
 5	
 6	import java.sql.Connection;
 7	import java.sql.PreparedStatement;
 8	import java.sql.ResultSet;
 9	import java.sql.SQLException;
 10	
 11	public class UserDAO {
 12	 public User getUserByUsername(String username) {
 13	 String sql = "SELECT * FROM users WHERE username = ?";
 14	 try (Connection conn = DBUtil.getInstance().getConnection();
 15	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 16	 stmt.setString(1, username);
 17	 ResultSet rs = stmt.executeQuery();
 18	
 19	 if (rs.next()) {
 20	 User user = new User();
 21	 user.setUsername(rs.getString("username"));
 22	 user.setPassword(rs.getString("password"));
 23	 user.setRole(rs.getString("role"));
 24	 return user;
 25	 }
 26	
 27	 } catch (SQLException e) {
 28	 e.printStackTrace();
 29	 }
 30	 return null;
 31	 }
 32	
 33	 public boolean createUser(String username, String hashedPassword, String role) {
 34	 String sql = "INSERT INTO users (username, password, role) VALUES (?, ?, ?)";
 35	 try (Connection conn = DBUtil.getInstance().getConnection();
 36	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 37	 stmt.setString(1, username);
 38	 stmt.setString(2, hashedPassword);
 39	 stmt.setString(3, role);
 40	 return stmt.executeUpdate() > 0;
 41	 } catch (SQLException e) {
 42	 e.printStackTrace();
 43	 }
