 2	
 3	import com.example.pahanaedubackend.model.Admin;
 4	import com.example.pahanaedubackend.service.AdminService;
 5	import com.fasterxml.jackson.databind.ObjectMapper;
 6	
 7	import javax.servlet.ServletException;
 8	import javax.servlet.annotation.WebServlet;
 9	import javax.servlet.http.HttpServlet;
 10	import javax.servlet.http.HttpServletRequest;
 11	import javax.servlet.http.HttpServletResponse;
 12	import javax.servlet.http.HttpSession;
 13	import java.io.IOException;
 14	import java.util.HashMap;
 15	import java.util.Map;
 16	
 17	@WebServlet("/login")
 18	public class LoginServlet extends HttpServlet {
 19	 private final AdminService adminService = new AdminService();
 20	
 21	 @Override
 22	 protected void doPost(HttpServletRequest request, HttpServletResponse response)
 23	 throws ServletException, IOException {
 24	
 25	 response.setContentType("application/json");
 26	 response.setCharacterEncoding("UTF-8");
 27	
 28	 ObjectMapper mapper = new ObjectMapper();
 29	 Map<String, String> data = mapper.readValue(request.getInputStream(), Map.class);
 30	
 31	 String username = data.get("username");
 32	 String password = data.get("password");
 33	
 34	 Admin admin = adminService.login(username, password);
 35	
 36	 Map<String, Object> result = new HashMap<>();
 37	 if (admin != null) {
 38	 HttpSession session = request.getSession(true);
 39	 session.setAttribute("admin", admin);
 40	
 41	 result.put("success", true);
 42	 result.put("message", "Login successful");
 43	 result.put("username", admin.getUsername());
 44	 } else {
 45	 result.put("success", false);
 46	 result.put("message", "Invalid username or password");
 47	 }
 48	
 49	 mapper.writeValue(response.getWriter(), result);
 50	 }
 51	}
