 13	public class CustomerDAO {
 14	 public boolean addCustomer(Customer customer) {
 15	 String sql = "INSERT INTO customer (account_number, full_name, telephone, address, units_consumed) VALUES (?, ?, ?, ?, ?)";
 16	
 17	 try (Connection conn = DBUtil.getInstance().getConnection();
 18	 PreparedStatement stmt = conn.prepareStatement(sql)) {
 19	
 20	 stmt.setString(1, customer.getAccountNumber());
 21	 stmt.setString(2, customer.getFullName());
 22	 stmt.setString(3, customer.getTelephone());
 23	 stmt.setString(4, customer.getAddress());
 24	 stmt.setInt(5, customer.getUnitsConsumed());
 25	
 26	 return stmt.executeUpdate() > 0;
 27	 } catch (SQLException e) {
 28	 e.printStackTrace();
 29	 return false;
 30	 }
 31	 }
