 63	
 64	 while (rs.next()) {
 65	 Customer customer = new Customer();
 66	 customer.setId(rs.getInt("id"));
 67	 customer.setAccountNumber(rs.getString("account_number"));
 68	 customer.setFullName(rs.getString("full_name"));
 69	 customer.setTelephone(rs.getString("telephone"));
 70	 customer.setAddress(rs.getString("address"));
 71	 customer.setUnitsConsumed(rs.getInt("units_consumed"));
 72	 customers.add(customer);
 73	 }
 74	 } catch (SQLException e) {
 75	 e.printStackTrace();
 76	 }
 77	
 78	 return customers;
